def hook(ctx, nb):
    try:
        if ctx['action']['tool'] != 'click_action':
            return None
        val = ctx['action']['value_normalized']
    except Exception:
        return None
    if val != 'buy now':
        return None
    try:
        need = ctx['predicates']['required_options_unselected']
    except Exception:
        need = False
    if not need:
        return None
    try:
        clicks = ctx['state']['clickables']
    except Exception:
        clicks = []
    try:
        obs = ctx['observation'].lower()
    except Exception:
        obs = ''
    skip = ['buy now', 'back to search', '< prev', 'next >', 'description', 'features', 'reviews', 'search']
    best = ''
    for c in clicks:
        raw = str(c)
        low = raw.lower().strip()
        if low in skip or low == '' or low == 'none' or low == 'n/a' or low == 'na':
            continue
        if low.startswith('[') and low.endswith(']'):
            continue
        clean = low.replace(' ', '')
        for ch in ['-', '_', '/', '(', ')', '[', ']', ',', ';', ':', '*']:
            clean = clean.replace(ch, '')
        clean_low = low.replace(' ', '')
        for ch in ['-', '_', '/', '(', ')', '[', ']', ',', ';', ':', '*']:
            clean_low = clean_low.replace(ch, '')
        match = False
        for key in ['color', 'size', 'material', 'flavor', 'count', 'style']:
            try:
                req = str(ctx['task'][key]).lower().strip()
            except Exception:
                req = ''
            r = req.replace(' ', '')
            for ch in ['-', '_', '/', '(', ')', '[', ']', ',', ';', ':', '*']:
                r = r.replace(ch, '')
            if req != '' and r != '' and (r in clean or r in clean_low):
                match = True
        if match and best == '':
            best = raw
    if best != '':
        return {'kind': 'block_and_prompt', 'message': 'Do not buy yet: a required product option is still unselected. Choose the visible option that matches the instruction, such as ' + best + ', then use Buy Now.'}
    return {'kind': 'block_and_prompt', 'message': 'Do not buy yet: a required product option is still unselected and no matching option is visible on this page. Go back to search results and choose a better matching item.'}
